class Dog {
  constructor(name, breed) {
    this.name = name;
    this.breed = breed;
  }

  bark() {
    return `${this.name}: Woof!`;
  }
}

const dog1 = new Dog("Buddy", "Labrador");
const dog2 = new Dog("Max", "Poodle");
console.log(dog1.bark()); // Buddy: Woof!

