public class Dog {
    private String name;
    private String breed;

    public Dog(String name, String breed) {
        this.name = name;
        this.breed = breed;
    }

    public String bark() {
        return name + ": Woof!";
    }
}

Dog dog1 = new Dog("Buddy", "Labrador");
System.out.println(dog1.bark()); // Buddy: Woof!

