public class Dog {
    public string Name { get; }
    public string Breed { get; }

    public Dog(string name, string breed) {
        Name = name;
        Breed = breed;
    }

    public string Bark() => $"{Name}: Woof!";
}

var dog1 = new Dog("Buddy", "Labrador");
Console.WriteLine(dog1.Bark()); // Buddy: Woof!

